INSERT INTO sys_permission (id,permission_code,permission_name,permission_type,resource_path,http_method,status,sort_order,created_at,updated_at) SELECT 'unified-ws-permission','workspace:permissions:access','权限管理工作空间','menu',NULL,NULL,'enabled',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code='workspace:permissions:access');
INSERT INTO sys_role_permission (id,tenant_id,role_id,permission_id,created_at,updated_at) SELECT LOWER(RAWTOHEX(HASH('MD5',STRINGTOUTF8(CONCAT('unified-ws-permission:',r.id))))),r.tenant_id,r.id,p.id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sys_role r JOIN sys_permission p ON p.permission_code='workspace:permissions:access' WHERE r.role_code='SUPER_ADMIN' AND r.status='enabled' AND EXISTS (SELECT 1 FROM sys_role_permission old JOIN sys_permission source ON old.permission_id=source.id WHERE old.role_id=r.id AND old.tenant_id=r.tenant_id AND source.permission_code='system:role:authorize' AND source.status='enabled') AND NOT EXISTS (SELECT 1 FROM sys_role_permission e WHERE e.role_id=r.id AND e.permission_id=p.id) AND NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code='system:unified-management:v1');
