INSERT INTO workspace_registry (id,status,access_permission_code,manifest_json,default_workspace,version,created_at,updated_at) SELECT 'permissions','enabled','workspace:permissions:access','{"schemaVersion":"workspace-manifest.v1","configVersion":1,"workspaceId":"permissions","appVersion":"2.0.0","name":"权限管理","icon":"shield-check","description":"统一管理用户、组织、角色、工具及数据范围授权","entryPage":"systemRoles","layoutType":"management","pages":[{"id":"systemUsers","menuCode":"systemUsers","componentKey":"systemUsers","props":{}},{"id":"systemOrganizations","menuCode":"systemOrganizations","componentKey":"systemOrganizations","props":{}},{"id":"systemRoles","menuCode":"systemRoles","componentKey":"systemRoles","props":{}},{"id":"systemResources","menuCode":"systemResources","componentKey":"systemResources","props":{}},{"id":"systemLogins","menuCode":"systemLogins","componentKey":"systemLogins","props":{}}],"requiredCapabilities":[],"optionalCapabilities":[],"defaultSkillIds":[]}',FALSE,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM workspace_registry WHERE id='permissions');
INSERT INTO workspace_registry (id,status,access_permission_code,manifest_json,default_workspace,version,created_at,updated_at) SELECT 'mcp-publication','enabled','workspace:mcp-publication:access','{"schemaVersion":"workspace-manifest.v1","configVersion":1,"workspaceId":"mcp-publication","appVersion":"2.0.0","name":"MCP 工具发布","icon":"package","description":"管理工具定义、测试、发布及版本回滚","entryPage":"toolPublications","layoutType":"assistant","pages":[{"id":"toolPublications","menuCode":"toolPublications","componentKey":"toolPublications","props":{}}],"requiredCapabilities":[],"optionalCapabilities":[],"defaultSkillIds":[]}',FALSE,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM workspace_registry WHERE id='mcp-publication');
INSERT INTO sys_menu (id,menu_code,menu_name,menu_type,route_path,icon,sort_order,status,created_at,updated_at) SELECT 'toolPublications','toolPublications','MCP 工具发布','menu','/index.html#/w/mcp-publication/toolPublications','shield-check',45,'enabled',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE menu_code='toolPublications');
INSERT INTO sys_menu_permission (id,menu_id,permission_id,created_at,updated_at) SELECT 'unified-menu:toolPublications',m.id,p.id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM sys_menu m JOIN sys_permission p ON p.permission_code='mcp:publication:read' WHERE m.menu_code='toolPublications' AND NOT EXISTS (SELECT 1 FROM sys_menu_permission e WHERE e.menu_id=m.id AND e.permission_id=p.id);
